#!/bin/bash
# build-toaru-cmini.sh - mini-commander for ToaruOS, compiled by cmini on the host:
#   cmini.bin -L /lib -c per source (pasm backend, -I cmini-toaru: the ToaruOS declarations
#   generated by cmini/gen_libc.py), the 8-bit curses shim and glue from toaruos-tools/cmini-curses,
#   calloc that zeroes memory, then pasm -k with ToaruOS crt0/crti/libc.a/crtn.
#
#   ./build-toaru-cmini.sh      => _build/cmini-toaru/mc-toaru.bin
#
# Needs: ../cmini/cmini.bin, ../asm/pasm.bin (make), ../toaruos-tools/_build/toaru-lib (mklibc.sh).
set -euo pipefail
HERE=$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)
TOP=$(cd "$HERE/.." && pwd)
CMINI=${CMINI:-$TOP/cmini/cmini.bin}
PASM=${PASM:-$TOP/asm/pasm.bin}
L=$TOP/_build/toaru-lib
SHIM=$TOP/toaruos-tools/cmini-curses
OUT=$TOP/_build/mini-commander/cmini-toaru
O=$OUT/obj
die() { echo "error: $*" >&2; exit 1; }
[[ -x $CMINI ]] || die "missing $CMINI (make -C cmini)"
[[ -x $PASM ]] || die "missing $PASM (make -C asm)"
[[ -f $L/libc.a ]] || die "missing $L (run toaruos-tools/mklibc.sh)"
rm -rf "$OUT"; mkdir -p "$O"

INC="-I $HERE/cmini-toaru -I $SHIM"
cc() { "$CMINI" -L "$L" $INC -D TOARU_CMINI=1 -D calloc=cm_calloc -c "$1" "$2" || die "cmini -c $2"; }

OBJS=""
for f in mc cmd operations dialog filelist init panel ui view_edit progress; do
    cc "$O/$f.o" "$HERE/$f.c"; OBJS="$OBJS $O/$f.o"
done
"$CMINI" -L "$L" -I "$SHIM" -I "$TOP/cmini/ownheaders" -c "$O/curses8.o" "$SHIM/curses8.c" || die "curses8"
"$CMINI" -L "$L" -c "$O/glue.o" "$SHIM/glue.c" || die "glue"
"$CMINI" -L "$L" -I "$TOP/cmini/ownheaders" -c "$O/calloc_zero.o" "$TOP/toaruos-tools/selfhost/calloc_zero.c" || die "calloc_zero"
OBJS="$OBJS $O/curses8.o $O/glue.o $O/calloc_zero.o"

"$PASM" -k "$OUT/mc-toaru.bin" "$L/crt0.o" "$L/crti.o" $OBJS "$L/libc.a" "$L/crtn.o" || die "link (see above: undefined symbols)"
echo "built: $OUT/mc-toaru.bin ($(stat -c%s "$OUT/mc-toaru.bin") B)"
